use std::io::{self, Read, Write};
use std::num::ParseIntError;

/// Parse one token. The error is the library's, passed straight through.
fn parse_one(tok: &str) -> Result<i64, ParseIntError> {
    tok.parse::<i64>()
}

/// Parse and then check a range. Two different failures, one error type.
fn parse_in_range(tok: &str, lo: i64, hi: i64) -> Result<i64, String> {
    let v = match parse_one(tok) {
        Ok(v) => v,
        Err(e) => return Err(format!("bad {}", e)),
    };
    if v < lo || v > hi {
        return Err(format!("range {}", v));
    }
    Ok(v)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let lo: i64 = match it.next() {
        Some(t) => t.parse().unwrap(),
        None => return,
    };
    let hi: i64 = it.next().unwrap().parse().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let mut good = 0i64;
    let mut bad = 0i64;
    let mut total = 0i64;

    for tok in it {
        match parse_in_range(tok, lo, hi) {
            Ok(v) => {
                good += 1;
                total += v;
                writeln!(out, "ok {}", v).unwrap();
            }
            Err(msg) => {
                bad += 1;
                writeln!(out, "err {} {}", tok, msg).unwrap();
            }
        }
    }

    writeln!(out, "good {}", good).unwrap();
    writeln!(out, "bad {}", bad).unwrap();
    writeln!(out, "total {}", total).unwrap();

    // unwrap_or_else: recover with a computed default instead of crashing
    let fallback = parse_in_range("not-a-number", lo, hi).unwrap_or_else(|_| -1);
    writeln!(out, "fallback {}", fallback).unwrap();

    io::stdout().flush().ok();
}
